(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["microbiology-exam-2"]={"title":"Microbiology Exam 2","sections":[{"id":"l7-scope","title":"L7 · What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-types","title":"L7 · Immunopathologies & the Four Hypersensitivities","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-allergy","title":"L7 · Type I in Detail, Diagnosis & Management","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-transfusion","title":"L7 · Transfusion Reactions & Rh","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-transplant","title":"L7 · Transplantation & Histocompatibility","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-auto-deficiency","title":"L7 · Autoimmunity & Immunodeficiency","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-cancer","title":"L7 · Carcinogenesis & Immunotherapy","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l8-categories","title":"L8 · Diagnosing Infections: The Three Categories","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l8-phenotypic","title":"L8 · Phenotypic Methods & Sensitivity Testing","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l8-genotypic-immuno","title":"L8 · Genotypic & Immunological Methods","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l9-scope","title":"L9 · Cocci: What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l9-tree","title":"L9 · The Gram-Positive Decision Tree","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l9-staph","title":"L9 · Staphylococci","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l9-strep","title":"L9 · Streptococci & Enterococci","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l9-viridans-pneumo","title":"L9 · Viridans Streptococci & the Pneumococcus","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l9-gneg","title":"L9 · Neisseria, Moraxella & Acinetobacter","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l10-scope","title":"L10 · What the Lecturer Flagged","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-sorting","title":"L10 · Sorting the Gram-Positive Bacilli","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-bacillus","title":"L10 · Bacillus anthracis & Bacillus cereus","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-clostridia","title":"L10 · Gas Gangrene, Tetanus & Botulism","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-difficile-regular","title":"L10 · C. difficile, Lactobacillus & Listeria","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-irregular","title":"L10 · Diphtheria & Cutibacterium","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-mycobacteria","title":"L10 · Tuberculosis & Leprosy","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l10-actino-transmission","title":"L10 · Actinomyces, Nocardia & Transmission","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l11-scope","title":"L11 · What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l11-why","title":"L11 · Resistance & Stewardship","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l11-choosing","title":"L11 · Choosing Antibiotics Today","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l11-prophylaxis","title":"L11 · Prophylaxis & Adverse Effects","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l11-fmt-phage","title":"L11 · Fecal Transplant & Phage Therapy","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l11-other","title":"L11 · Other Alternatives","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"}],"rows":[{"t":"★ Learn this table","d":"The four-hypersensitivity summary table (slide 9): “a chart you should pay attention to.”","s":0},{"t":"★ The one mechanism","d":"Desensitization works by raising allergen-specific immunoglobulin G that BLOCKS the allergen from the immunoglobulin E on mast cells.","s":0},{"t":"★ No type I","d":"Type I plays NO part in graft rejection or in autoimmunity. Both use II, III and IV.","s":0},{"t":"★ B cell vs T cell defect","d":"B cell defect (agammaglobulinemia) → recurrent BACTERIAL infections. T cell defect → fungal, viral, protozoan.","s":0},{"t":"Not to memorize","d":"Helminth-allergen pairings (slide 6) · graft versus host grades (slide 50) · autoimmune disease charts (slides 58–60) · the order of the transformation sequence (slide 67). Oncogenic virus table (slide 68) deferred to the virus lectures.","s":0},{"t":"Four immunopathologies","d":"OVER: allergy/hypersensitivity, autoimmunity (typically). UNDER: immunodeficiency, cancer (both a cause and an effect of immune dysfunction).","s":1},{"t":"Hypersensitivity","d":"Exaggerated, misdirected response to an allergen using the SAME mechanisms as protective immunity. I, II, III = B cell mediated; IV = T cell mediated.","s":1},{"t":"Type I","d":"IMMEDIATE. Immunoglobulin E on mast cells, basophils, eosinophils is crosslinked → mediators. Hay fever, hives, anaphylactic shock.","s":1},{"t":"Type II","d":"Immunoglobulin G/M against CELL SURFACE antigen → complement, lysis by membrane attack complex, phagocytosis. Transfusion reactions, Rh disease, autoimmune hemolytic anemia, myasthenia gravis.","s":1},{"t":"Type III","d":"Immunoglobulin G/M against SOLUBLE antigen → immune complexes in basement membranes. Needs lots of antigen; delayed hours to days; joints, skin, kidney. Serum sickness, Arthus reaction, post-streptococcal glomerulonephritis, lupus, rheumatoid arthritis.","s":1},{"t":"Type IV","d":"DELAYED, T cell mediated. Infectious allergy (tuberculosis, leprosy, syphilis, histoplasmosis, toxoplasmosis, candidiasis), tuberculin test, contact dermatitis, graft rejection.","s":1},{"t":"Hygiene hypothesis","d":"Helminths give the allergic profile with less allergic disease, for two proposed reasons: nonspecific immunoglobulin E crowds Fc receptors and regulatory T cells suppress. Remove the worms (sanitation, treatment) and the idea is that the immune system is underused and poorly regulated.","s":1},{"t":"Asthma crosses types","d":"Acute = type I (bronchospasm, mucus). Chronic = TYPE IV (cytokines, eosinophil granules).","s":1},{"t":"Sensitizing vs provocative dose","d":"FIRST contact: immunoglobulin E made and parked on mast cells, no symptoms. LATER contact: allergen crosslinks it → degranulation. 10,000–40,000 immunoglobulin E per cell.","s":2},{"t":"Skin","d":"Urticaria = skin mast cells + histamine. Angioedema = DEEPER mast cells. Eczema = PROLONGED response. Food urticaria: antigen carried to the skin in blood.","s":2},{"t":"Anaphylaxis","d":"Cutaneous = wheal and flare (used in diagnosis). Systemic = fluid leaves blood → pressure falls → swelling → asphyxiation. 500–1000 deaths a year in the United States.","s":2},{"t":"Epinephrine (5 actions)","d":"Reseals endothelial tight junctions · relaxes bronchi · reduces airway mucosal edema · stimulates heart · suppresses histamine release.","s":2},{"t":"Late phase","d":"About 6 HOURS after the immediate reaction; synthesized mediators such as leukotrienes; eosinophils; tissue more sensitive next time.","s":2},{"t":"Diagnosis","d":"Allergy or infection? Skin prick/intradermal (wheal and flare) · blood: specific immunoglobulin E (a raised basophil count is not a reliable allergy marker) · supervised food challenge · PATCH test = contact dermatitis (type IV).","s":2},{"t":"Drugs","d":"Corticosteroids ↓ immunoglobulin E via lymphocytes · cromolyn blocks degranulation · montelukast blocks leukotriene action (receptor blocker) · omalizumab = anti-immunoglobulin E antibody · antihistamines block receptors.","s":2},{"t":"Desensitization","d":"Subcutaneous immunotherapy most common; ~80% improve. Also regulatory T cells. Sublingual: under the tongue; peanut dose 1/75 of a kernel.","s":2},{"t":"Why ABO","d":"Red cells carry NO major histocompatibility complex molecules. You make antibody against the ABO antigens you LACK.","s":3},{"t":"Cross-match","d":"RECIPIENT serum against DONOR red cells — never the reverse (too little donor antibody to react).","s":3},{"t":"Consequences","d":"Complement lysis → blocked glomeruli, fever, jaundice; coated cells also cleared by natural killer cells and macrophages.","s":3},{"t":"Rh disease","d":"Rh-negative mother, Rh-positive fetus. First pregnancy sensitizes; later ones hemolytic (erythroblastosis fetalis).","s":3},{"t":"Rhogam timing","d":"Passive anti-Rh antibody prevents sensitization. 26–28 WEEKS · within 72 HOURS of birth · after invasive tests, abdominal injury, accidental exposure.","s":3},{"t":"Graft types","d":"Autograft = self · isograft = identical twin · allograft = same species · xenograft = other species.","s":4},{"t":"★ Rejection by type","d":"Hyperacute = II (preexisting antibody; engorged, purple graft) · acute = IV (T cells vs human leukocyte antigen differences) · chronic = III (thickened vessel walls) · graft versus host = IV.","s":4},{"t":"Chronic rejection","d":"Months to years; fails MORE THAN HALF of kidney and heart transplants after 10+ years.","s":4},{"t":"Acute rejection route","d":"Graft dendritic cells → SPLEEN → activate effector T cells → back via blood → graft destroyed.","s":4},{"t":"Cornea","d":"First organ transplanted; succeeds WITHOUT a human leukocyte antigen match — eye downregulates T cells, macrophages, neutrophils, complement.","s":4},{"t":"Liver","d":"Human leukocyte antigens NOT assessed; ABO IS. Hepatocytes: little class I, no class II.","s":4},{"t":"Bone marrow","d":"MOST sensitive to mismatch → graft versus host disease (skin, muscle, liver, gut) in ~30%.","s":4},{"t":"Preventing rejection","d":"Tissue typing, mixed lymphocyte reaction; purine analogs, corticosteroids, tacrolimus, cyclosporine, rapamycin (sirolimus).","s":4},{"t":"Autoimmunity","d":"Lost tolerance → autoantibodies and sensitized T cells. All types EXCEPT I. Runs in families; WOMEN more often.","s":5},{"t":"Sequestered antigen","d":"Privileged tissue (central nervous system, lens, thyroid, testes) damaged later releases unseen antigen. One injured eye → T cells attack BOTH.","s":5},{"t":"Molecular mimicry","d":"Rheumatic fever (strep → heart) · Lyme arthritis (Borrelia) · reactive arthritis (Shigella, Salmonella, Campylobacter) · type 1 diabetes (coxsackie A/B, echovirus, rubella).","s":5},{"t":"Thymic senescence","d":"Thymus involutes to fat; premature aging in young people with autoimmunity; less output → infection, cancer, autoimmunity.","s":5},{"t":"Slide 61 diseases","d":"Graves' (stimulates follicle cells → hyper) · Hashimoto's (destroys them → hypo) · myasthenia gravis (acetylcholine receptors) · multiple sclerosis (myelin; T cells + antibody; Epstein-Barr link).","s":5},{"t":"Primary vs secondary","d":"PRIMARY = congenital, genetic. SECONDARY = acquired after birth: human immunodeficiency virus (T helper cells), chemotherapy, radiation, blood cell cancers.","s":5},{"t":"Primary examples","d":"Agammaglobulinemia (B, no antibody) · DiGeorge (T, no thymus) · severe combined immunodeficiency (both limbs, no adaptive response) · complement, phagocyte defects.","s":5},{"t":"Transformation","d":"ONE cell with MULTIPLE accumulated mutations; oncogenes activated by radiation, chemicals, oncogenic viruses. Benign = contained; malignant = spreads.","s":6},{"t":"Cancer cell traits","d":"Self-stimulating · ignore stop signals · no apoptosis · angiogenesis · metastasis · constant replication · evade immunity.","s":6},{"t":"Tumor antigens","d":"SPECIFIC = tumor only. ASSOCIATED = tumor + normal cells (less).","s":6},{"t":"Evasion","d":"Shed the natural killer stress ligand · secrete transforming growth factor beta → regulatory T cells (+ interleukin 10). In many cancers, more regulatory T cells = WORSE prognosis.","s":6},{"t":"Checkpoint inhibitors","d":"Block the T cell OFF signal; do not kill directly. Melanoma, some lung cancers.","s":6},{"t":"Adoptive cell therapy","d":"Patient's cells engineered and returned. CAR-T (chimeric antigen receptor T cells) APPROVED for blood cancers; tumor infiltrating lymphocytes APPROVED for advanced melanoma (lifileucel, 2024) and studied in other solid tumors; chimeric antigen receptor natural killer cells in trials.","s":6},{"t":"Antibodies & cytokines","d":"100+ monoclonal antibodies, diagnosis AND therapy; conjugates carry drug or radionuclide. Interleukin 2 → T and natural killer cells (kidney, melanoma). Interferon alpha → natural killer and dendritic cells. Erythropoietin = red cells; interleukin 11 = platelets.","s":6},{"t":"Coley · viruses · vaccines","d":"Coley's toxins (1890s; killed strep + Serratia; displaced by radiation and chemotherapy). Oncolytic viruses replicate only in tumor cells; mumps natural. Prophylactic: hepatitis B, papillomavirus. Therapeutic: bacillus Calmette-Guérin (bladder), sipuleucel-T (prostate).","s":6},{"t":"Scope note","d":"The objectives are the course-wide list; the lecture teaches diagnostic METHODS. Sort every technique into one of three.","s":7},{"t":"Phenotypic","d":"Observable traits (phenotype = physical expression of genes): morphology, biochemistry, chemistry, drug sensitivity. Needs culture → SLOWER.","s":7},{"t":"Genotypic","d":"Genetic makeup; NO culture needed — slow Mycobacterium, hard Legionella. Faster diagnosis → timely treatment.","s":7},{"t":"Immunological","d":"Antigen-antibody specificity; culture optional. Rapid strep 10–15 minutes, but you need a hypothesis first, and a negative rapid test can still miss infection.","s":7},{"t":"Specimens","d":"ALL potentially infectious. Results depend on collection, handling, transport, storage. Universal precautions MITIGATE, not eliminate.","s":7},{"t":"Results","d":"Direct tests or culture-isolation-identification; results PRESUMPTIVE or CONFIRMATORY.","s":7},{"t":"Morphology","d":"Microscopic: shape, size, stain (Gram, flagellar, acid-fast), structures. Macroscopic: colony texture, size, shape, pigment.","s":8},{"t":"Biochemical","d":"Presence or absence of enzymes/pathways: fermentation, amino acids, hydrolysis, catalase, oxidase, coagulase, hemolysins.","s":8},{"t":"★ Blood agar","d":"Detects HEMOLYSIS — the lecturer's “take-home message”, especially for pathogenic Gram-positives.","s":8},{"t":"Other media","d":"Chocolate agar: ENRICHED medium for fastidious organisms, grown in extra carbon dioxide (candle jar) — NOT anaerobic, whatever the slide says · mannitol salts: selects salt tolerance, differentiates mannitol · citrate: blue = pH up · urea: hot pink = urease.","s":8},{"t":"Normal flora?","d":"Is the recovered organism the cause, or normal flora? Koch's postulates reasoning.","s":8},{"t":"Kirby-Bauer","d":"Disk diffusion: WHICH drugs the microbe is susceptible or resistant to; for one drug a LARGER zone = more susceptible (zones of different drugs cannot be ranked). Minimum inhibitory concentration strips give the concentration.","s":8},{"t":"Polymerase chain reaction","d":"Thermal cycler amplifies nucleic acid; Kary Mullis. Guanine + cytosine content = taxonomy, not specific identification.","s":9},{"t":"Ribosomal ribonucleic acid","d":"16S for bacteria, 18S for eukaryotes → phylogenetic trees. Restriction fragment length polymorphism = “fingerprinting.”","s":9},{"t":"Serology","d":"In vitro testing of serum; titer in binding antibody units. Serotyping = known antibody identifies an unknown microbe.","s":9},{"t":"Agglutination vs precipitation","d":"Agglutination = WHOLE-CELL/insoluble antigen, clumps, MORE sensitive (blood typing, syphilis, Weil-Felix, pregnancy, rapid strep). Precipitation = SOLUBLE antigen, needs gel/liquid (Ouchterlony, immunoelectrophoresis → antibody class).","s":9},{"t":"Blots","d":"Southern = deoxyribonucleic acid (the man's name) · Northern = ribonucleic acid · WESTERN = PROTEIN, long the second test for human immunodeficiency virus (now replaced by a second immunoassay plus nucleic acid testing) · Eastern = other epitopes.","s":9},{"t":"★ Complement fixation","d":"“Absolutely backwards.” 4 parts: antigen, antibody, complement, sheep red cells. NO hemolysis = POSITIVE. Cells burst (hemolysis) = negative.","s":9},{"t":"Fluorescent · immunoassay · in vivo","d":"Dye-labeled monoclonal antibody, direct or indirect. Immunoassays detect TRACE amounts (radioimmunoassay; enzyme-linked immunosorbent assay, 96-well, high throughput). In vivo: tuberculin, allergy tests.","s":9},{"t":"★ Allergy testing","d":"A fairly rapid antigen-antibody reaction on the skin: the antibody class is immunoglobulin E (type I).","s":9},{"t":"Viruses","d":"Not cells; need a host cell (human or animal tissue culture) → labor intensive to culture; rapid point-of-care antigen-antibody tests.","s":9},{"t":"★ Yellow highlights","d":"The deck's 14 yellow-highlighted passages are her emphasis (“I tried to highlight some things”). Starred rows below.","s":10},{"t":"★ M-protein","d":"“This M protein, which you might also want to highlight”: M-protein → resistance to PHAGOCYTOSIS (Streptococcus pyogenes).","s":10},{"t":"★ Lancefield A and B","d":"“The A and the B are the primo ones.” Group A = Streptococcus pyogenes; group B = Streptococcus agalactiae.","s":10},{"t":"Not to memorize","d":"“Don't worry about digging down into the Lancefield letters”: the minor groups (C, G and the letters in the slide 26 table) · the rate maps and STD (sexually transmitted disease) graphs, slides 62–66.","s":10},{"t":"★ Gram stain","d":"Gram-positive = THICK peptidoglycan = physically strong. Gram-negative = thin = chemically strong. Staph = irregular CLUSTERS; strep = CHAINS.","s":11},{"t":"★ Staph always","d":"Non-spore-forming and non-motile (no spores, no flagella); may have capsules.","s":11},{"t":"★ Catalase","d":"Hydrogen peroxide: bubbles = staphylococci (+). No bubbles = streptococci and enterococci (−).","s":11},{"t":"Coagulase","d":"Coagulase + = Staphylococcus aureus (97% of isolates; the diagnostic trait). Coagulase − = the other staphylococci.","s":11},{"t":"★ Hemolysis","d":"Blood agar detects hemolysis. BETA = complete, clear zone (A, B, C, G, some D). ALPHA = partial, GREEN (pneumococcus, viridans).","s":11},{"t":"Bacitracin / optochin","d":"Beta + bacitracin SENSITIVE = group A (Streptococcus pyogenes); resistant = B, C. Alpha + optochin SENSITIVE = Streptococcus pneumoniae; resistant = D, viridans.","s":11},{"t":"Salt","d":"Staphylococcus aureus withstands high salinity (mannitol salts agar). Streptococci grow poorly on it — too saline.","s":11},{"t":"Staphylococcus aureus","d":"Golden (“aureus”) colonies, 37°C, FACULTATIVE anaerobe; tolerates salt, pH, heat. Carried in the ANTERIOR NARES (20–60% of adults).","s":12},{"t":"Enzymes","d":"Coagulase clots plasma · staphylokinase digests clots · hyaluronidase digests connective tissue · lipases aid skin colonization · penicillinase inactivates penicillin.","s":12},{"t":"Toxins","d":"Hemolysins lyse red cells · LEUKOCIDIN lyses neutrophils and macrophages · ENTEROTOXIN = gut distress · EXFOLIATIVE splits the upper epidermis · TSST (toxic shock syndrome toxin) = fever, vomiting, shock.","s":12},{"t":"Skin","d":"Folliculitis (follicle) → FURUNCLE (boil, abscess) → CARBUNCLE (cluster of joined furuncles). Impetigo: bubble-like swellings that break and peel.","s":12},{"t":"Systemic & toxigenic","d":"Osteomyelitis in the METAPHYSIS · bacteremia from another site or a DEVICE (endocarditis risk) · food intoxication = HEAT-STABLE enterotoxin · scalded skin · toxic shock (classically tampons).","s":12},{"t":"Treatment & prevention","d":"95% make penicillinase. Methicillin-resistant strains: multiple resistance, now COMMUNITY acquired too; older teaching says some resist all but VANCOMYCIN, but vancomycin and several newer drugs still work against most strains. Abscess = surgical drainage. Universal precautions; don't share towels, razors.","s":12},{"t":"Coagulase-negative","d":"Nosocomial, opportunistic, start polymicrobial BIOFILMS. Epidermidis: skin, mucosa → endocarditis, bacteremia, UTI (urinary tract infection). Hominis: apocrine (lipid-rich) armpit and groin. Capitis: scalp, face, ear. All three: wound infection via broken skin. Saprophyticus: may cause UTI.","s":12},{"t":"General","d":"Chains, facultative anaerobes, FASTIDIOUS (enriched media), sensitive to drying, heat, disinfectants. Lancefield = cell wall C-CARBOHYDRATE antigens (Rebecca Lancefield, 1933).","s":13},{"t":"★ Group A virulence","d":"C-carbohydrate vs lysozyme · fimbriae adhere · M-PROTEIN vs phagocytosis · hyaluronic acid capsule = little immune response (looks like the body's own) · C5a protease blocks complement · streptolysins O, S = hemolysins · erythrogenic toxin = fever + rash · superantigens · streptokinase digests fibrin.","s":13},{"t":"★ Group A spread","d":"STRICTLY human; humans the only reservoir. Contact, droplets, food, fomites; portal skin or pharynx; mostly CHILDREN.","s":13},{"t":"Group A disease","d":"Impetigo = contagious CRUST, schoolchildren · erysipelas = into dermis and subcutaneous tissue · pharyngitis · scarlet fever = PROPHAGE for erythrogenic toxin · septicemia, pneumonia, toxic shock.","s":13},{"t":"Group A sequelae","d":"Rheumatic fever after pharyngitis → valve damage, arthritis, chorea. Acute glomerulonephritis → nephritis, high blood pressure, kidney failure.","s":13},{"t":"★ Group B","d":"Streptococcus agalactiae: vagina, pharynx, large intestine. Reaches the infant during VAGINAL DELIVERY → top cause of neonatal pneumonia, sepsis, meningitis. SCREEN and treat pregnant women (intravenous penicillin in practice; slide's streptomycin is wrong).","s":13},{"t":"Enterococci (group D)","d":"Separated from Streptococcus by 16S ribosomal RNA (1984). Large intestine; urinary, wound, skin infection in the debilitated; MULTIPLE antibiotics.","s":13},{"t":"Identification","d":"Rapid tests = monoclonal antibody to C-carbohydrate. Culture: bacitracin, CAMP, bile esculin. CAMP factor + beta-hemolytic Staphylococcus aureus = FLAME or ARROW; also detects Listeria.","s":13},{"t":"Treatment","d":"Groups A and B: PENICILLIN. Long-term penicillin after rheumatic fever or recurrent strep throat. ★ Big problems with resistant strains.","s":13},{"t":"★ Viridans","d":"Most numerous in gums, teeth, mouth. Not very invasive: DENTAL or SURGICAL procedures let them in. Worst = SUBACUTE ENDOCARDITIS (pre-existing heart disease).","s":14},{"t":"Streptococcus mutans","d":"Slime layers on teeth → PLAQUE and caries. Dental prophylaxis now only for certain heart conditions.","s":14},{"t":"Pneumococcus: lab","d":"LANCET-shaped pairs and short chains · blood or chocolate agar · CAPNOPHILIC (5–10% carbon dioxide) · lacks catalase AND peroxidase, dies in high lab oxygen.","s":14},{"t":"Pneumococcus: disease","d":"Large CAPSULE = main virulence factor (types vary). Pneumonia by ASPIRATION; otitis media via the EUSTACHIAN TUBE. Endogenous; very young, elderly, compromised, crowded.","s":14},{"t":"Pneumococcus: treatment","d":"Penicillin, but rising resistance. Conjugate vaccine for children 2–23 months; capsular vaccine for older adults (adults now also get conjugate vaccines).","s":14},{"t":"Neisseria","d":"Gram-negative BEAN-shaped DIPLOCOCCI, thin peptidoglycan, no flagella or spores, PILI attach. Strict human parasites. Microaerophilic. Catalase + and cytochrome OXIDASE +.","s":15},{"t":"★ Culture","d":"Chocolate agar in a CANDLE JAR = enhanced carbon dioxide (not an anaerobic culture).","s":15},{"t":"Gonococcus","d":"Fimbriae · IgA protease (immunoglobulin A). Dose 100–1,000 cells; 1–2 hours on fomites. Asymptomatic: 50% of females, 10% of males. Salpingitis → sterility, ectopic pregnancy. Arthritis, conjunctivitis, pharyngitis.","s":15},{"t":"Gonococcus: diagnosis","d":"Gram-negative diplococci INSIDE NEUTROPHILS = presumptive. Penicillinase-producing and tetracycline-resistant strains. No lasting immunity → recurs. Reportable. Newborn eyes: topical antibiotics at birth.","s":15},{"t":"Meningococcus","d":"Capsule, fimbriae, IgA protease, ENDOTOXIN (hemorrhage, shock). Nasopharynx; close quarters, DORMS; 6 months–3 years and 10–20 years. Blood → blood-brain barrier → cerebrospinal fluid.","s":15},{"t":"Meningococcus: care","d":"Culture slow → rapid capsular polysaccharide tests. Intravenous penicillin G or cephalosporin; prophylaxis for CLOSE CONTACTS (medical personnel only after direct exposure to secretions); vaccine = purified capsular antigens.","s":15},{"t":"Moraxella","d":"Branhamella catarrhalis, RECLASSIFIED into Moraxella; nasopharynx; opportunist in cancer, diabetic, alcoholic patients.","s":15},{"t":"★ Acinetobacter","d":"Acinetobacter baumannii: multidrug-resistant COCCOBACILLI, hospital acquired, especially in MILITARY hospitals. (The genus lives in soil; this species is a hospital organism.)","s":15},{"t":"★ Two scope rules","d":"No percentages, case counts or mortality figures (“I'm not going to be testing you on the percentages”). No antibiotic choice (“that's what we have our PDRs [Physicians' Desk References] for”).","s":16},{"t":"★ What IS examinable","d":"“What is the most common, what's the deadliest, how the different things work.”","s":16},{"t":"★ Spore position","d":"Bacillus = CENTRAL spore. Clostridium = TERMINAL spore (drumstick, “tennis racket”).","s":16},{"t":"★ Named must-knows","d":"Clostridium perfringens = commonest gas gangrene; mixed infection; floppy baby syndrome; diphtheria pseudomembrane; Propionibacterium → Cutibacterium; three stages of tuberculosis; Actinomyces israelii harmful only in deeper tissue.","s":16},{"t":"Not to memorize","d":"Names of the 17 myonecrosis toxins (know what they do) · Erysipelothrix (slides 57–58) · Mycobacterium species chart (slide 68) · non-tuberculous mycobacteria (slide 90).","s":16},{"t":"Two properties","d":"Endospores and acid-fastness → spore-formers, regular non-spore-formers, irregular non-spore-formers.","s":17},{"t":"Bacillus","d":"Aerobic (or facultative), catalase POSITIVE, central spore, soil saprobe; makes bacitracin, gramicidin, subtilin.","s":17},{"t":"Clostridium","d":"Obligately anaerobic, catalase NEGATIVE, terminal spore made only under anaerobic conditions; among the most toxic exotoxins on earth.","s":17},{"t":"Regular","d":"Stain uniformly, one shape: Lactobacillus, Listeria, Erysipelothrix.","s":17},{"t":"Irregular","d":"Pleomorphic, stain unevenly: Corynebacterium, Cutibacterium, Mycobacterium (acid-fast), Actinomyces and Nocardia (filamentous). Corynebacterium and Mycobacterium have mycolic acids.","s":17},{"t":"B. anthracis","d":"Large block-shaped rods in chains, central spores; Koch's postulates; zoonosis; Category A bioterrorism agent; polypeptide capsule.","s":18},{"t":"Three-part toxin","d":"Protective antigen = receptor site for the other two · edema factor impairs phagocytosis · lethal factor lyses macrophages at high levels → cytokine surge → septic-shock picture.","s":18},{"t":"★ Cutaneous","d":"MOST COMMON. Spores through a cut → painless papule → ulcer with vesicles → black necrotic eschar.","s":18},{"t":"★ Pulmonary","d":"DEADLIEST. Woolsorters' disease: inhaled spores; macrophages die en masse; shock; half get meningitis.","s":18},{"t":"Other forms","d":"Gastrointestinal = eaten infected meat (mouth and esophageal ulcers). Injection = heroin, deep muscle. Meningitis can follow ANY form.","s":18},{"t":"Anthrax care","d":"Pulmonary also gets antitoxin. Biothrax = purified toxoid for high-risk workers and military (not under 18 or over 65); livestock get live spores.","s":18},{"t":"B. cereus","d":"Foodborne (rice, potatoes, meat); spores survive cooking and reheating. Diarrheal = large protein toxin; emetic = small heat-stable peptide. About 24 hours, no treatment.","s":18},{"t":"B. cereus extras","d":"Sepsis from contaminated alcohol prep pads · eye infections, pneumonia · welder's anthrax = anthrax toxin made by B. cereus.","s":18},{"t":"★ Gas gangrene","d":"Clostridium perfringens. Needs dead tissue + low oxygen: deep dirty wounds, compound fractures. ★ MIXED infection — aerobes use up the oxygen.","s":19},{"t":"Gangrene details","d":"Gas = fermented muscle carbohydrate. Spread = collagenase, hyaluronidase. Cellulitis stays local; true myonecrosis spreads with fever and necrosis. Debride, hyperbaric oxygen; NO vaccine.","s":19},{"t":"Perfringens food","d":"Meat, fish; toxin made IN THE INTESTINE; mild, rapid recovery. Botulism = rare but severe.","s":19},{"t":"Tetanus","d":"Puncture wounds, umbilical stump (neonates). Tetanospasmin blocks gamma-aminobutyric acid and glycine → UNCONTROLLED contraction; death by respiratory failure (spasm of the breathing muscles and larynx). Shorter incubation = worse.","s":19},{"t":"Tetanus care","d":"Antitoxin neutralizes CIRCULATING, not bound, toxin; muscle relaxants; booster every 10 years. Commonest in older adults and drug users.","s":19},{"t":"Botulism","d":"Botulin blocks ACETYLCHOLINE at the junction → DESCENDING flaccid paralysis. Double vision, trouble swallowing first. Ventilators cut mortality.","s":19},{"t":"Botulism sources","d":"Low-acid home-canned food (air out, spores survive). ★ Infant = MOST COMMON: swallowed spores, honey → floppy baby. Wound = black tar heroin. Iatrogenic = medical toxin use.","s":19},{"t":"Botulism care","d":"Antitoxin + cardiac and respiratory support. Prevent: discard bulging cans, boil home-bottled food 10 minutes.","s":19},{"t":"C. difficile","d":"Clostridioides (split off by ribonucleic acid sequencing). Low-number colon resident; broad-spectrum antibiotics kill competitors → overgrowth → enterotoxins.","s":20},{"t":"C. difficile disease","d":"Pseudomembranous colitis (sloughed necrotic lining), toxic megacolon, perforation. Major hospital diarrhea. Risk: antibiotics, long stays, age, gastric acid inhibitors.","s":20},{"t":"C. difficile care","d":"Mild: fluids + stop the antibiotic. Fecal microbiota transplant restores flora. Precautions against spread.","s":20},{"t":"Lactobacillus","d":"Gut and vaginal flora; lactic acid, acetic acid, hydrogen peroxide. Antibiotics → opportunist superinfection.","s":20},{"t":"Listeria","d":"Coccobacilli to filaments, no capsule. GROWS IN THE FRIDGE. Replicates in host cytoplasm → avoids antibody. Soil, water, animal gut → dairy, poultry, meat.","s":20},{"t":"Listeria disease","d":"Mild in healthy adults; brain and meninges in the immunocompromised, fetuses, neonates. Culture = cold enrichment. Prevent = pasteurize and cook.","s":20},{"t":"Diphtheria spread","d":"Healthy carriers; respiratory droplets; non-immunized children in crowding.","s":21},{"t":"★ Pseudomembrane","d":"Solidified inflammatory fluid in the throat — characteristic; can asphyxiate.","s":21},{"t":"Diphtheria toxin","d":"Targets the HEART (myocarditis) and NERVES (weakness, paralysis).","s":21},{"t":"Diphtheria lab & care","d":"Palisades, granules; alkaline methylene blue. Horse-serum antitoxin neutralizes circulating toxin only. Prevent: toxoid series + boosters.","s":21},{"t":"★ Cutibacterium acnes","d":"Formerly Propionibacterium. Pilosebaceous glands; nontoxigenic; acne via inflammatory mediators.","s":21},{"t":"Implant infections","d":"Biofilm on prosthetics; grows over 6 days, needs prolonged anaerobic culture; hardware removal, debridement, months of antibiotics.","s":21},{"t":"Mycobacteria","d":"Acid-fast (mycolic acids, waxes); strict aerobes; catalase; no capsules, flagella or spores; slow.","s":22},{"t":"Tubercle bacillus","d":"No exotoxins; waxes + cord factor resist macrophages. Airborne droplets; infectious dose about 10 cells. Latent = not contagious, can reactivate.","s":22},{"t":"★ Three stages","d":"PRIMARY: tubercles (granulomas), caseous lesions calcify. SECONDARY: reactivation, tubercles drain into bronchi, “consumption”. DISSEMINATED: nodes, kidneys, bones, meninges.","s":22},{"t":"Tuberculosis tests","d":"Mantoux read at 48–72 hours (type IV). QuantiFERON = gamma interferon. False +: BCG (bacille Calmette-Guérin), other mycobacteria. False −: too early, immunosuppression. Ziehl-Neelsen sputum.","s":22},{"t":"Tuberculosis care","d":"Two or more drugs for months; vaccine = attenuated Mycobacterium bovis (used abroad).","s":22},{"t":"Mycobacterium leprae","d":"Not cultivable → armadillos; slowest growing; globi; skin macrophages and Schwann cells. Transmission not fully verified; armadillos possible.","s":22},{"t":"Two forms","d":"TUBERCULOID (T helper 1): shallow lesions, local pain loss. LEPROMATOUS (T helper 2): nodular, disseminated, T cells barely respond; treated far longer.","s":22},{"t":"Leprosy diagnosis","d":"Numbness, lost heat and cold sense, thick earlobes, stuffy nose; acid-fast bacilli in lesions; feather test.","s":22},{"t":"Filamentous bacilli","d":"Actinomyces and Nocardia: nonmotile, filamentous, related to mycobacteria.","s":23},{"t":"★ A. israelii","d":"Harmless mouth, gut, genital resident — disease only in DEEPER tissue. Cervicofacial ← oral infection · thoracic · abdominal ← burst appendix · uterine ← intrauterine device.","s":23},{"t":"A. viscosus","d":"Dental caries; some endocarditis.","s":23},{"t":"Nocardia","d":"Pulmonary disease like tuberculosis (can cross the chest wall to brain, kidneys); mycetoma = deep granulomatous inflammation.","s":23},{"t":"Objective 2 at a glance","d":"Cut, inhaled, eaten, injected spores (anthrax) · food (B. cereus, Listeria, botulism) · deep wounds (perfringens, tetanus) · own flora after antibiotics (C. difficile) · droplets (diphtheria, tuberculosis) · armadillos? (leprosy) · deeper tissue (Actinomyces).","s":23},{"t":"★ Not to memorize","d":"Dates (“Don't worry about dates”): slide 8's discovery/use/resistance years, phage-therapy decades, centuries of fecal therapy · vancomycin's mechanism (“don't worry about this”) · the parasitic-worm aside and the garden photos · success percentages.","s":24},{"t":"★ Phages, two properties","d":"VERY specific to their host bacterium · DIE OFF once that host is gone.","s":24},{"t":"★ Diagnosis first","d":"Phage therapy needs the causative agent identified — slow or fastidious growers (Mycobacterium, Legionella) make that time-consuming.","s":24},{"t":"★ Fecal transplant","d":"Researched for (recurrent) Clostridioides difficile — her class study gave it by nasogastric tube vs colonoscopy.","s":24},{"t":"Drivers of resistance","d":"Agricultural overuse (plants, animals) · inappropriate prescribing → STEWARDSHIP (clinician + patient education) · prophylaxis · patient NON-COMPLIANCE.","s":25},{"t":"Resistance","d":"The antibiotic can no longer kill or control the bacteria — a property of the BUG, not a patient allergy.","s":25},{"t":"Stewardship cycle","d":"DIAGNOSE bacterial disease → consider a NON-ANTIBIOTIC alternative → use antimicrobials JUDICIOUSLY when needed → RE-EVALUATE the need.","s":25},{"t":"Six facts","d":"Life-saving · bacterial infections ONLY · some ear infections and MOST sore throats need none · green mucus ≠ antibiotic · every drug has risks (allergy, rash, diarrhea).","s":25},{"t":"Resistance follows use","d":"Over 100 antibiotics on the market; penicillin, vancomycin, azithromycin each met resistance within years of widespread use.","s":25},{"t":"Superbugs","d":"MRSA/MSSA · VRSA/VISA · toxigenic Escherichia coli · Clostridioides difficile · Neisseria gonorrhoeae · Mycobacterium tuberculosis · carbapenem-resistant Klebsiella · vancomycin-resistant Enterococcus · Pseudomonas. ESKAPE pathogens top the NOSOCOMIAL lists.","s":25},{"t":"Disk diffusion (Kirby-Bauer)","d":"Antibiotic paper disks on inoculated agar → ZONE OF INHIBITION = drug stopped growth. Growth up to the disk = little effect.","s":26},{"t":"Antibiogram","d":"Susceptibility PERCENTAGES by organism and drug → guides EMPIRIC therapy. Vancomycin covered both MSSA and MRSA on the example.","s":26},{"t":"Antibiogram limits","d":"No minimum inhibitory concentration · no patient risk factors · no synergy data · may be ONE hospital only.","s":26},{"t":"Empiric therapy","d":"Started BEFORE cultures/results · critically ill or emergent · based on experience + antibiograms · then ADJUSTED (e.g. intravenous → oral). Not the same as prophylaxis.","s":26},{"t":"When prophylaxis","d":"Prosthetic devices (BIOFILM) · before surgery (surgical site infection) · immunocompromised (human immunodeficiency virus, chemotherapy, transplant) · CONTACTS of tuberculosis, meningitis, pertussis · dental work only for a few high-risk (prosthetic valve, prior endocarditis) · animal bites, penetrating brain injury.","s":27},{"t":"Direct adverse effects","d":"Allergy (even life-threatening) · kidney/liver toxicity · drug-drug interactions · therapeutic failure.","s":27},{"t":"Indirect adverse effects","d":"Commensal flora damage → Clostridioides difficile · resistant infection · ENVIRONMENTAL flora (antibiotics in food and water).","s":27},{"t":"Fecal microbiota transplant","d":"Screened DONOR STOOL restores the gut flora · centuries old (“yellow soup”) · researched for Clostridioides difficile; recurrent infection is its established use.","s":28},{"t":"Routes and safety","d":"Nasogastric tube · colonoscopy · enema (recording adds frozen oral capsules) · STOOL BANKS · donor screening like BLOOD BANKS: human immunodeficiency virus, hepatitis A/B/C, syphilis, Clostridioides difficile, Giardia, Cryptosporidium. Vets: “transfaunation”.","s":28},{"t":"Bacteriophages","d":"Viruses that attack ONLY bacteria · DNA or RNA, never both · lytic or lysogenic · therapy needs LYTIC phages · head holds the genome; tail, baseplate, tail fibers attach and inject.","s":28},{"t":"Phage pros","d":"Multidrug-resistant targets · NARROW spectrum spares the microbiome · low side effects · wide distribution · less inflammation · maybe cheaper · die off with their host.","s":28},{"t":"Phage cons","d":"Dose/route/frequency/duration undefined · MUST know the causative agent (slow, costly) · gene transfer to the host bacterium · insurance · no phage product approved as a medicine yet → investigational drug status, emergency use authorization. Abandoned in the West when antibiotics arrived.","s":28},{"t":"Host-directed","d":"Systemic CORTICOSTEROIDS ↓ inflammation (no killing) · intravenous immunoglobulin G and CONVALESCENT plasma (antibodies from recovered donors).","s":29},{"t":"Prebiotic vs probiotic","d":"PREbiotic = fiber that feeds the flora · PROBIOTIC = the live organism: Lactobacillus (bacterium), Saccharomyces (fungus), in FERMENTED foods.","s":29},{"t":"Diet","d":"The more diverse your PLANT intake, the more diverse your gut microbiota (American Gut project).","s":29},{"t":"Plant essential oils","d":"Antibacterial IN VITRO; better experimental design needed. Spice use predicted heaviest in HOT climates with rapid food spoilage.","s":29}],"map":{"microbiology-exam-2-cocci-of-medical-importance-quiz-version-2":[75,82,84,-1,87,87,77,76,74,79,78,78,94,71,90,-1,92,93,93,95,97,-1,103,-1,102,-1,102,107,108,109],"microbiology-exam-2-cocci-of-medical-importance-quiz":[74,77,81,83,84,87,87,87,-1,80,76,-1,79,72,71,92,93,93,94,97,-1,-1,103,-1,-1,-1,-1,-1,108,109],"microbiology-exam-2-diagnosing-infections-quiz-version-2":[-1,64,65,-1,54,56,67,59,50,60,60,50,51,56,68,-1,-1,69,51,52,176,63,52,-1,-1,58,61,55,55,66],"microbiology-exam-2-diagnosing-infections-quiz":[68,52,-1,66,65,64,50,63,64,51,63,60,58,61,66,-1,53,52,57,64,-1,-1,58,62,64,-1,-1,53,64,-1],"microbiology-exam-2-disorders-in-immunity-quiz-version-2":[25,6,43,-1,12,-1,46,-1,12,5,27,29,26,14,21,38,-1,39,45,9,32,39,-1,41,-1,41,21,43,5,34],"microbiology-exam-2-disorders-in-immunity-quiz":[21,-1,36,10,3,-1,-1,-1,26,23,6,-1,37,45,11,-1,2,-1,-1,-1,20,3,-1,5,36,11,36,44,39,26],"microbiology-exam-2-gram-positive-bacilli-quiz-version-2":[-1,-1,122,155,128,147,141,154,136,134,39,-1,126,148,116,112,140,128,-1,130,131,-1,126,121,157,142,134,143,122,178],"microbiology-exam-2-gram-positive-bacilli-quiz":[-1,141,-1,127,-1,-1,123,-1,151,131,-1,155,140,155,126,125,129,117,148,134,-1,125,128,131,-1,-1,150,146,137,116],"microbiology-exam-2-novel-antimicrobial-therapy-quiz-version-2":[180,170,184,-1,183,181,178,175,171,169,163,178,182,180,186,170,174,175,165,167,178,175,178,174,186,173,178,180,-1,176],"microbiology-exam-2-novel-antimicrobial-therapy-quiz":[182,180,175,170,-1,168,178,-1,178,178,174,182,-1,175,182,180,175,171,169,184,180,162,186,178,186,165,176,170,178,165]}};
